import { useState, useRef, ChangeEvent } from 'react';
import { Mic, Paperclip, Send } from 'lucide-react';

interface ChatInterfaceProps {
    handleSend: (message: string, attachment?: File) => void;
    // ... other props ...
}

export const ChatInterface = ({ handleSend }: ChatInterfaceProps) => {
    const [userMsg, setUserMsg] = useState('');
    const [attachment, setAttachment] = useState<File | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleFileSelect = (e: ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            setAttachment(e.target.files[0]);
        }
    };

    const handleSendClick = () => {
        if (userMsg.trim() || attachment) {
            handleSend(userMsg.trim(), attachment);
            setUserMsg('');
            setAttachment(null);
            if (fileInputRef.current) {
                fileInputRef.current.value = ''; // Reset the input field
            }
        }
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            handleSendClick();
        }
    };

    return (
        <div className="flex flex-col w-full h-20 items-center justify-center p-3">
            <div className="flex w-full items-center justify-between">
                {/* ... Chat Input ... */}
            </div>
            {attachment && (
                <div className="flex items-center gap-2 mt-2">
                    <span>{attachment.name}</span>
                    <button onClick={() => setAttachment(null)} className="text-red-500">
                        Remove
                    </button>
                </div>
            )}
            <div className="flex w-full items-center">
                <input
                    type="file"
                    ref={fileInputRef}
                    onChange={handleFileSelect}
                    className="hidden"
                    accept=".pdf,.doc,.docx,.txt"
                />
                <button
                    onClick={() => {
                        if (fileInputRef.current) {
                            fileInputRef.current.click();
                        }
                    }}
                    className="absolute right-2 flex items-center justify-center rounded-full p-2 hover:bg-gray-200"
                >
                    <Paperclip className="w-4 h-4" />
                </button>
                {/* ... Send button ... */}
            </div>
        </div>
    );
};
```


